+            !dominators.dominates(values.second, use))
+          return std::nullopt;
+        node.insertion = use;
+      }
+      return found->second;
+    }
+
+    PackNode node;
+    node.values = values;
+    node.insertion = use;
+    auto *first = dyn_cast<Instruction>(values.first);
+    auto *second = dyn_cast<Instruction>(values.second);
